import{_ as i,C as s,o as t,c as d,a2 as o,b as n,w as r,a as c,E as p,a3 as l}from"./chunks/framework.Bqn-bhhR.js";const w=JSON.parse('{"title":"Repository Registry & Worktrees","description":"","frontmatter":{},"headers":[],"relativePath":"guide/repository-registry.md","filePath":"guide/repository-registry.md","lastUpdated":1786047222000}'),h={name:"guide/repository-registry.md"};function m(g,e,k,u,y,b){const a=s("Mermaid");return t(),d("div",null,[e[1]||(e[1]=o('<h1 id="repository-registry-worktrees" tabindex="-1">Repository Registry &amp; Worktrees <a class="header-anchor" href="#repository-registry-worktrees" aria-label="Permalink to &quot;Repository Registry &amp; Worktrees&quot;">​</a></h1><p>Codemark is <strong>Git-aware by default</strong>. It detects the current repository, tracks bookmarks by a durable identity, and supports multi-repo queries. This page covers how repos are registered and discovered, in <code>crates/codemark-core/src/storage/registry.rs</code>, <code>workspace.rs</code>, and <code>git/context.rs</code>.</p><h2 id="two-tier-registry-model" tabindex="-1">Two-tier registry model <a class="header-anchor" href="#two-tier-registry-model" aria-label="Permalink to &quot;Two-tier registry model&quot;">​</a></h2><p>Codemark tracks repositories at two levels:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Location</th><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Per-repo DB</strong></td><td><code>&lt;repo_root&gt;/.codemark/codemark.db</code> → <code>repos</code> table</td><td><code>origin_url</code> AND <code>repo_root</code> (both unique)</td><td>Each repo worked in is a row here; bookmarks reference <code>repo_id</code>.</td></tr><tr><td><strong>Global registry</strong></td><td>data dir → <code>registry.db</code> → <code>known_repos</code> table</td><td><code>repo_root</code> (unique)</td><td>Cross-repo discovery and identity-by-name.</td></tr></tbody></table><p>The split is deliberate: the global registry recognizes a <em>moved</em> repo by its durable <code>(repo_owner, repo_name)</code> identity rather than by the per-DB <code>id</code> (a <code>Uuid::new_v4()</code> regenerated whenever <code>.codemark/</code> is recreated).</p><h2 id="how-a-repo-is-identified" tabindex="-1">How a repo is identified <a class="header-anchor" href="#how-a-repo-is-identified" aria-label="Permalink to &quot;How a repo is identified&quot;">​</a></h2><p><code>detect_repo_metadata</code> resolves a working directory to an identity:</p><ol><li><strong><code>git rev-parse --git-common-dir</code></strong> → its parent is the repo root. This is <em>worktree-aware</em>: every linked worktree shares the main repo&#39;s <code>.git</code>, so all worktrees resolve to the <strong>same repo root</strong> and share the same database.</li><li><strong><code>git remote get-url origin</code></strong> → the origin URL.</li><li><strong><code>parse_git_url</code></strong> strips <code>.git</code>, handles SSH (<code>git@host:path</code>) and https/http/ssh schemes, and takes the last two path segments as <code>owner/name</code> (handling GitLab subgroups).</li></ol><p>Local repos with no origin get <code>None</code> for their identity and are tracked by <code>repo_root</code> alone.</p><h2 id="registration-reconciliation" tabindex="-1">Registration &amp; reconciliation <a class="header-anchor" href="#registration-reconciliation" aria-label="Permalink to &quot;Registration &amp; reconciliation&quot;">​</a></h2><p>Every CLI invocation needing repo metadata runs <code>resolve_or_create_repo_metadata</code>, which reconciles both tiers:</p>',12)),(t(),n(l,null,{default:r(()=>[p(a,{id:"mermaid-95",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22CLI%20invocation%22%5D%20--%3E%20B%5B%22detect_context%5Cn(git%20rev-parse%20--git-common-dir)%5Cn%E2%86%92%20repo_root%2C%20worktree-aware%22%5D%0A%20%20B%20--%3E%20C%5B%22detect_repo_metadata%5Cnorigin%20%E2%86%92%20parse_git_url%20%E2%86%92%20owner%2Fname%22%5D%0A%20%20C%20--%3E%20D%5B%22per-DB%20repos%20table%5Cnfind%20by%20origin_url%20or%20repo_root%5Cnupsert%20on%20drift%2C%20else%20create%22%5D%0A%20%20D%20--%3E%20E%5B%22sync_to_global_registry%5Cn%E2%86%92%20reconcile_repo%22%5D%0A%20%20E%20--%3E%20F%5B%22find_move_predecessor%5Cnby%20origin_url%20%2B%20owner%2Fname%5Cnat%20a%20now-missing%20path%22%5D%0A%20%20F%20--%3E%20G%5B%22UPSERT%20known_repos%5Cnon%20repo_root%20conflict%5CnCOALESCE%20server_url%22%5D%0A%20%20G%20--%3E%20H%5B%22done%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o(`<p><code>reconcile_repo</code> is transactional and smart about moves: if it finds a row with the same <code>origin_url</code> + <code>(repo_owner, repo_name)</code> at a path that no longer exists on disk, it treats it as a move — inherits its <code>server_url</code>/<code>default_username</code>, deletes the predecessor, and upserts at the new path. Sync never auto-prunes (a missing path might be a temporarily unmounted volume); <code>codemark repo prune</code> is opt-in.</p><h2 id="multi-repo-queries" tabindex="-1">Multi-repo queries <a class="header-anchor" href="#multi-repo-queries" aria-label="Permalink to &quot;Multi-repo queries&quot;">​</a></h2><p>Two flags widen the scope of any command, repeatable:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><code>--db &lt;path&gt;</code></td><td><strong>Override</strong> (if non-empty and not just primary)</td><td>Use only those database paths.</td></tr><tr><td><code>--repo owner/name</code></td><td><strong>Identity</strong></td><td>Resolve via the global registry → open <code>&lt;repo_root&gt;/.codemark/codemark.db</code>.</td></tr><tr><td><code>[databases].additional</code></td><td><strong>Additive</strong></td><td>From <code>.codemark/config.toml</code>: the primary (&quot;local&quot;) plus these extra paths.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Query across multiple repositories by identity</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codemark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> facebook/react</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme/api</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Combine with filters</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codemark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;authentication&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> facebook/react</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --health</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> active</span></span></code></pre></div><p>Additional databases are <strong>read-only</strong> — write operations affect only the primary DB.</p><h2 id="git-worktrees" tabindex="-1">Git worktrees <a class="header-anchor" href="#git-worktrees" aria-label="Permalink to &quot;Git worktrees&quot;">​</a></h2><p>Because worktrees share the main repo&#39;s <code>.git</code> (detected via <code>--git-common-dir</code>), they all resolve to the same repo root and therefore the same <code>.codemark/codemark.db</code>. Your bookmarks are accessible from any worktree of the same repository without duplication.</p><h2 id="the-codemark-repo-commands" tabindex="-1">The <code>codemark repo</code> commands <a class="header-anchor" href="#the-codemark-repo-commands" aria-label="Permalink to &quot;The \`codemark repo\` commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>repo list</code></td><td>List all known repositories in the global registry.</td></tr><tr><td><code>repo show [owner/name]</code></td><td>Show details for a repository (defaults to current).</td></tr><tr><td><code>repo set-server &lt;url&gt;</code></td><td>Set the default sync server URL for a repository.</td></tr><tr><td><code>repo sync</code></td><td>Re-reconcile the current path — the &quot;I moved the repo&quot; repair command.</td></tr><tr><td><code>repo prune [--dry-run]</code></td><td>Remove entries whose <code>repo_root</code> no longer exists.</td></tr></tbody></table>`,10))])}const f=i(h,[["render",m]]);export{w as __pageData,f as default};
